 CREATE OR REPLACE FUNCTION public.getprovidersearchlist(agency_name character varying, ssbg_ character varying, type_key character varying, fiscal_year integer, size numeric, page numeric)                       
  RETURNS TABLE(agencyname character varying, name character varying, provideragreementtypekey character varying, ssbg character varying, agencyid uuid, agencygroupid uuid, federaltaxid character varying)        
  LANGUAGE plpgsql                                                                                                                                                                                                  
 AS $function$                                                                                                                                                                                                      
                                                                                                                                                                                                                    
 BEGIN                                                                                                                                                                                                              
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
 RETURN QUERY                                                                                                                                                                                                       
                                                                                                                                                                                                                    
 select A.agencyname ,AA.name,AGPT.ProviderAgreementTypeKey,PA.ssbg, A.agencyid,A1.AgencyGroupId,PA.federaltaxid                                                                                                    
   from Agency AS  A,Agency AS  A1 ,AgencyAlias AS AA,ProviderAgreement AS PA,AgencyGroup AS AG,AgencyGroupProviderAgreementTypeMap AS AGPT,AgencyGroupProviderAgreementTypeMap AS AGTP1                            
      where A.AgencyGroupId in(select  AGTP1.AgencyGroupId from AgencyGroupProviderAgreementTypeMap where AGTP1.ProviderAgreementTypeKey LIKE type_key|| '%' AND  AGTP1.FiscalYear ::text  LIKE  fiscal_year || '%')
          AND  A.agencygroupid = A1.AgencyGroupId                                                                                                                                                                   
           AND  A.agencyid = A1.AgencyId                                                                                                                                                                            
           AND AGPT.agencyid = A.agencyid                                                                                                                                                                           
           AND  AA.agencyid = AGPT.agencyid                                                                                                                                                                         
           AND PA.agencyid = AA.agencyid                                                                                                                                                                            
           AND AG.agencygroupId = AGPT.agencygroupId                                                                                                                                                                
           AND CASE WHEN agency_name is null THEN TRUE ELSE A.agencyname LIKE agency_name|| '%' END                                                                                                                 
          AND CASE WHEN ssbg_ is null THEN TRUE ELSE PA.ssbg LIKE ssbg_ || '%' END                                                                                                                                  
           group by A.agencyname ,AA.name,AGPT.ProviderAgreementTypeKey, A.agencyid,A1.AgencyGroupId,PA.federaltaxid ,PA.ssbg                                                                                       
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
  LIMIT size OFFSET  (page - 1) * size ;                                                                                                                                                                            
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
                                                                                                                                                                                                                    
 END; $function$                                                                                                                                                                                                    

